import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects input missing a required property and does not invoke the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsLocationAndRequired: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsLocationAndRequired: true,
    });
  });

  it('rejects a wrong-typed property naming the field and expected type without leaking the value to result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_user',
        description: 'Look up user by SSN',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('lookup_user', {ssn: 987654321});

    expect({
      executorCalls,
      mentionsField: response.result.includes('ssn'),
      mentionsType: response.result.includes('string'),
      leaksInResult: response.result.includes('987654321'),
      leaksInLogs: recordedLogs.some(line => line.includes('987654321')),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      mentionsType: true,
      leaksInResult: false,
      leaksInLogs: false,
    });
  });

