function formatValidationErrors(errors: ErrorObject[]): string[] {
  return errors.map(formatValidationError);
}

function formatValidationError(error: ErrorObject): string {
  const path = error.instancePath ? error.instancePath.replace(/^\//, '').replace(/\//g, '.') : '';
  if (error.keyword === 'required' && typeof error.params.missingProperty === 'string') {
    const missing = path ? `${path}.${error.params.missingProperty}` : error.params.missingProperty;
    return `missing required property "${missing}"`;
  }
  const target = path || 'input';
  if (error.keyword === 'type' && typeof error.params.type === 'string') {
    return `${target} must be ${error.params.type}`;
  }
  return `${target} failed ${error.keyword} constraint`;
}

